import re
def forms():
    out = []
    for i, c in enumerate(C):
        out += [(f"c{i}", c), (f"c{i}/lower", c.lower()), (f"c{i}/upper", c.upper()), (f"c{i}/nospace_lower", re.sub(r"\s+", "", c).lower())]
    seen, uniq = set(), []
    for t, v in out:
        if v and v not in seen: seen.add(v); uniq.append((t, v))
    return uniq
def selftest():
    return "TENETE" in C
